import React, { useRef, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import MessageBubble from "./MessageBubble";
import ChatInput from "./ChatInput";
import { sendMessage } from "../../redux/slices/chatSlice";

export default function ChatWindow() {
  const dispatch = useDispatch();
  const { messages, status } = useSelector((state) => state.chat);
  const bottomRef = useRef(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSend = (message) => {
    dispatch(sendMessage({ message, sessionId: "default", repId: null }));
  };

  return (
    <div className="card">
      <h3>Chat with the AI Agent</h3>
      <div className="chat-window">
        {messages.length === 0 && (
          <p style={{ color: "#98a2b3", fontSize: 14 }}>
            Try: "Met Dr. Rao today, discussed the new trial dosage, she was positive about it"
          </p>
        )}
        {messages.map((m, idx) => (
          <MessageBubble key={idx} role={m.role} content={m.content} />
        ))}
        <div ref={bottomRef} />
      </div>
      <ChatInput onSend={handleSend} disabled={status === "loading"} />
    </div>
  );
}
